[1012] = { en = "Insane Druids", tier = 2,
  t = "Krankzinnige druïden",
  d = "Toen ik vocht tegen het gif van de Forsaken, kreeg ik een visioen. Ik zag de druïden in de Dor'danil Barrow Den, vergiftigd... vermoord door de ondoden! Nu zijn ze dwalende geesten. Ze zijn losgerukt van hun lichamen en gek geworden.$B$BZodat de geesten van de druïden ooit rust kunnen vinden, moet je de Dor'danil Barrow Den in gaan. Vernietig daar de leiders die ooit zo groot waren: Taneel Darkwood, Uthil Mooncall en Mavoris Cloudsbreak.$B$BDoe dit en kom dan terug bij mij.",
  o = "Dood de druïden: Taneel Darkwood, Uthil Mooncall, Mavoris Cloudsbreak; ga dan terug naar Kayneth Stillwind in Forest Song.",
  p = "De pijn van de druïden van Dor'danil achtervolgt nog steeds mijn dromen, $N. Je moet hun leiders vernietigen!",
  c = "Ik voelde dat de pijn in de Dor'danil Barrows minder werd. Toen wist ik dat je je taak had voltooid.$B$BHet was somber werk, $N. De geesten die je hebt vernietigd waren namelijk alleen maar slachtoffers van het kwaad van de Forsaken. Maar laten we hopen dat de andere gek geworden geesten rust vinden, nu deze vernietigd zijn.",
  g = { {"Krankzinnige", "insane (krankzinnig)"}, {"gif", "poison"}, {"visioen", "vision"}, {"vergiftigd", "poisoned (vergiftigen)"}, {"ondoden", "undead"}, {"dwalende", "wandering, errant (dwalen)"}, {"losgerukt", "torn away, severed (losrukken)"}, {"rust", "peace, rest"}, {"Vernietig", "destroy (vernietigen)"}, {"achtervolgt", "haunts (achtervolgen)"}, {"voltooid", "completed (voltooien)"}, {"somber", "grim"}, {"slachtoffers", "victims (slachtoffer)"}, {"kwaad", "evil"} },
},

[1021] = { en = "Vile Satyr! Dryads in Danger!", tier = 2,
  t = "Gemene saters! Dryaden in gevaar!",
  d = "Luister, ik weet niet wie je bent, maar ik heb je hulp nodig. Mijn zussen zijn de Branch of Cenarius gaan terughalen bij de saters. Ze zeiden dat ze snel terug zouden zijn, maar het is al twee hele dagen geleden!$B$B$n, je moet ze vinden! Ze zochten de ruïnes van een tempel van de nachtelfen in Xavian, in het noordoosten. Ik weet niet wat ik moet denken. Zoek Anilia; zij leidde de zoektocht.",
  o = "Vind Anilia in Xavian.",
  c = "Aan de grote, open wond in haar zij te zien, staat Anilia op het punt te sterven.",
  g = { {"Gemene", "vile (gemeen)"}, {"saters", "satyrs (sater)"}, {"Dryaden", "dryads (dryade)"}, {"terughalen", "to take back"}, {"ruïnes", "ruins"}, {"nachtelfen", "night elves"}, {"noordoosten", "northeast"}, {"leidde", "led (leiden)"}, {"zoektocht", "search"}, {"Aan ... te zien", "judging by"}, {"wond", "wound"}, {"zij", "side (of the body)"}, {"op het punt te sterven", "on the verge of death"} },
},

[1031] = { en = "The Branch of Cenarius", tier = 2,
  t = "De Branch of Cenarius",
  d = "Anilia legt haar handen op je schouders en trekt je dicht naar zich toe. Hijgend wijst ze naar de boog in het noorden. Dan gaan haar ogen dicht en verlaat haar laatste piepende adem haar lichaam. \"Hij heeft hem gepakt... Geltharis...\" In je hart weet je wat Anilia's laatste wens is: ze wil de Branch of Cenarius weer in handen van de dryaden zien.",
  o = "Dood Geltharis en breng de Branch of Cenarius terug naar Illiyana bij de Shrine of Aessina.",
  p = "Heb je ze gevonden? Wat zei Anilia? Waar is ze?",
  c = "Is Anilia dood? Nee... dat kan niet! Gisteren renden en speelden we nog samen in het bos.$B$BDie dagen zijn nu zeker voorbij...",
  g = { {"schouders", "shoulders (schouder)"}, {"trekt ... naar zich toe", "draws close (naar zich toe trekken)"}, {"Hijgend", "gasping (hijgen)"}, {"wijst", "points (wijzen)"}, {"boog", "arch"}, {"verlaat", "leaves (verlaten)"}, {"piepende", "wheezing (piepen)"}, {"adem", "breath"}, {"wens", "wish"}, {"in handen van", "in the hands of"}, {"voorbij", "over"} },
},

[1032] = { en = "Satyr Slaying!", tier = 2,
  t = "Saters doden!",
  d = "Ik kan niet geloven dat Anilia er niet meer is... We speelden altijd samen in de bossen. Ik voel me bijna... verdrietig.$B$BIk weet iets waardoor ik me misschien beter voel. Dood alsjeblieft de saters die Anilia van me hebben afgepakt! Breng me hun hoorns als bewijs van wat je hebt gedaan, dan ben ik je voor altijd dankbaar.$b$b",
  o = "Breng 16 Satyr Horns naar Illiyana in de Shrine of Aessina.",
  p = "Help me alsjeblieft om de dood van Anilia te wreken.",
  c = "Dank je wel, vriendelijke $R. De geest van mijn zus wordt blij van al je moeite.",
  g = { {"saters", "satyrs (sater)"}, {"verdrietig", "sad"}, {"waardoor", "through which, because of which"}, {"afgepakt", "taken away (afpakken)"}, {"hoorns", "horns (hoorn)"}, {"bewijs", "proof"}, {"dankbaar", "grateful"}, {"wreken", "to avenge"}, {"geest", "spirit"}, {"moeite", "effort"} },
},

[7863] = { en = "Sentinel Basic Care Package", tier = 2,
  t = "Eenvoudig zorgpakket van de Sentinels",
  c = "Je bent echt begonnen om je aan ons te bewijzen, $N. Als beloning krijg je dit zorgpakket! Er zitten rantsoenen en verband in die je alleen in Warsong Gulch kunt gebruiken. $B$BAls je je in de Gulch blijft bewijzen, kun je deze spullen later ook kopen. Rantsoenen kun je kopen als je Friendly bij ons bent, en verband als je Honored bent.",
