},

[1178] = { en = "Goblin Sponsorship", tier = 3,
  t = "Goblin-sponsoring",
  d = "Ons raceteam is de trots van alle goblins. Je zou verbaasd zijn wie er allemaal op de een of andere manier aan ons team bijdraagt.$b$bKen je Gazlowe? Hij zoekt over de hele wereld onderdelen voor ons. Hij is zelfs een keer hierheen gekomen om aan een van onze wagens te werken!$b$bEen paar weken geleden zei hij dat hij ons een nieuw prototype van een brandstofregelaar zou sturen. Maar het is nog niet gekomen. Meestal is hij heel stipt... Wil je misschien naar Ratchet gaan om het hem te vragen? Ik zou niet zo aandringen, maar de gnomen komen steeds dichterbij!",
  o = "Spreek met Gazlowe in Ratchet.",
  c = "Pozzik heeft je gestuurd, hè? Weet je, Pozzik was een van de meest gerespecteerde knutselaars in Undermine, voordat hij met pensioen ging om aan de racewagens te werken.$b$bHet eerste wat hij deed toen hij bij het team kwam: hij ontwikkelde de racewagens met twee motoren. Misschien lijden de bedrijven eronder dat hij niet meer met de Tinkers' Union werkt, maar wat maakt het uit, toch? Er gaat niets boven de races!",
  g = { {"trots", "pride"}, {"verbaasd", "surprised"}, {"bijdraagt", "contributes (bijdragen)"}, {"onderdelen", "parts (onderdeel)"}, {"brandstofregelaar", "fuel regulator"}, {"stipt", "prompt, punctual"}, {"aandringen", "to be pushy, to insist"}, {"gerespecteerde", "respected (gerespecteerd)"}, {"knutselaars", "tinkerers (knutselaar)"}, {"met pensioen ging", "retired (met pensioen gaan)"}, {"ontwikkelde", "developed (ontwikkelen)"}, {"lijden", "suffer"}, {"Er gaat niets boven", "nothing beats"} },
},

[1180] = { en = "Goblin Sponsorship", tier = 3,
  t = "Goblin-sponsoring",
  d = "Terug naar waarvoor je hier kwam. Ik weet dat ik Pozzik heb beloofd dat ik een nieuwe brandstofregelaar voor hem zou leveren. Maar ik heb hem zelf nog steeds niet ontvangen. Revilgaz in Booty Bay zei dat hij hem hierheen zou laten verschepen. Maar misschien is hij op de een of andere manier tussen wal en schip geraakt.$b$bAls dat zo is, kunnen we er niet veel aan doen. We kunnen wel uitzoeken of hij uit Booty Bay is verstuurd.$b$bVraag het aan Wharfmaster Lozgil daar. Hij kan de vrachtlijsten controleren.",
  o = "Spreek met Wharfmaster Lozgil in Booty Bay.",
  c = "Zendingen naar Ratchet? Even de logboeken bekijken...$b$bNee, de laatste zending naar Ratchet in mijn lijsten was een lading laarzen van Drizzlik. Verder is er niet veel geweest, behalve bouwmaterialen en gereedschap. Zeker geen raceonderdelen.",
  g = { {"beloofd", "promised (beloven)"}, {"leveren", "to deliver"}, {"ontvangen", "received"}, {"verschepen", "to ship"}, {"tussen wal en schip geraakt", "slipped through the cracks"}, {"uitzoeken", "to find out"}, {"verstuurd", "sent, dispatched (versturen)"}, {"vrachtlijsten", "cargo records"}, {"Zendingen", "shipments (zending)"}, {"logboeken", "logbooks"}, {"lading", "load, cargo"}, {"bouwmaterialen", "building supplies"}, {"gereedschap", "tools"} },
},

[1181] = { en = "Goblin Sponsorship", tier = 3,
  t = "Goblin-sponsoring",
  d = "Ik ben bang dat ik je niet veel verder kan helpen, $n. Als je hier verder achteraan wilt gaan, raad ik je aan om naar de baron zelf te gaan. Als iemand de zaken van Revilgaz kent, is het Revilgaz.$b$bJe vindt hem in de herberg aan de overkant van de haven, op de bovenste verdieping.",
  o = "Spreek met Baron Revilgaz in Booty Bay.",
  c = "O, natuurlijk weet ik waar je het over hebt. Maar nee, ik kan je niet helpen. Een paar van mijn mannen moesten de bouwtekeningen van de brandstofregelaar gaan zoeken, maar ze kwamen met lege handen terug.",
  g = { {"achteraan wilt gaan", "want to follow up (achteraan gaan)"}, {"raad ik je aan", "I suggest to you (aanraden)"}, {"zaken", "business"}, {"herberg", "tavern, inn"}, {"aan de overkant van", "across, on the other side of"}, {"haven", "harbor"}, {"verdieping", "floor, storey"}, {"bouwtekeningen", "blueprints"}, {"met lege handen", "empty-handed"} },
},

[1182] = { en = "Goblin Sponsorship", tier = 3,
  t = "Goblin-sponsoring",
  d = "Kijk, de shredders van de Venture Company bij Lake Nazferiti (in het noorden van Stranglethorn) hebben een nieuw model brandstofregelaar gekregen. Ik dacht dat Pozzik daar zijn voordeel mee kon doen, als hij wat details kon krijgen. Helaas lijkt Cozzle, de voorman daar, iets slimmer te zijn dan ik dacht.$b$bMaar jij hebt misschien meer geluk met het vinden van de bouwtekeningen. Ik weet dat hij ze in zijn huis bewaart, maar ze liggen vrijwel zeker achter slot en grendel.",
  o = "Breng de Fuel Regulator Blueprints naar Baron Revilgaz in Booty Bay.",
  p = "Hoe vervelend ik het ook vind om toe te geven: dat gnomenteam van hen is best goed. Onze jongens hebben elk voordeel nodig dat ze kunnen krijgen.",
  c = "Zo, ik maak even een kopie van deze bouwtekeningen voor mijn eigen aantekeningen. Daarna kun je ze meteen naar Pozzik brengen. Ik wil niet dat hij denkt dat een van zijn sponsors hem in de steek laat.",
  g = { {"zijn voordeel mee kon doen", "could take advantage of it (zijn voordeel doen met)"}, {"Helaas", "unfortunately"}, {"voorman", "foreman"}, {"slimmer", "cleverer (slim)"}, {"bewaart", "keeps (bewaren)"}, {"vrijwel zeker", "almost certainly"}, {"achter slot en grendel", "under lock and key"}, {"toe te geven", "to admit (toegeven)"}, {"voordeel", "advantage, edge"}, {"aantekeningen", "notes"}, {"in de steek laat", "abandons (in de steek laten)"} },
},

[1183] = { en = "Goblin Sponsorship", tier = 3,
  t = "Goblin-sponsoring",
  d = "Je bent er helemaal klaar voor. Doe Pozzik de groeten van mij. Zeg hem dat hij nooit moet aarzelen om iets te vragen als hij iets nodig heeft. Ik wacht op het nieuws dat hij binnenkort het baanrecord breekt!",
  o = "Bezorg de Fuel Regulator Blueprints bij Pozzik op de Shimmering Flats.",
  p = "$n! Is het je gelukt om de brandstofregelaar te vinden?",
  c = "Ik hoopte dat hij al in elkaar gezet zou zijn. Maar zo heb ik de unieke kans om het ontwerp vanaf de basis te verbeteren. Bedankt, $n. Nu kan ik betere schema's tekenen, het ding bouwen en het heel snel installeren.",
