},

[1186] = { en = "The Eighteenth Pilot", tier = 3,
  t = "De achttiende piloot",
  d = "Ik ga het druk hebben met het verwerken van deze nieuwe brandstofregelaar in de ontwerpen van onze racewagens. Maar als je het team nog meer wilt helpen, praat dan met Razzeric. Hij is onze piloot... nou ja, onze achttiende piloot, om precies te zijn. Hij voegt graag zijn eigen kleine aanpassingen toe aan de racewagens.$b$bHij is wel een beetje gek, dus probeer niet te verbaasd te doen.",
  o = "Spreek met Razzeric op de Shimmering Flats.",
  c = "Jij bent de $r die Pozzik heeft geholpen, toch? Ik was ooit net als jij. Ik rende rond in de pits en hielp met al het werk dat de monteurs me lieten doen.$b$bEn kijk nu eens naar me! De geweldige piloot van het goblinraceteam!",
  g = { {"achttiende", "eighteenth"}, {"verwerken", "integrating, working in"}, {"ontwerpen", "designs (ontwerp)"}, {"om precies te zijn", "to be exact"}, {"voegt ... toe", "adds (toevoegen)"}, {"aanpassingen", "modifications (aanpassing)"}, {"verbaasd te doen", "to act surprised"}, {"pits", "pit area"}, {"monteurs", "mechanics (monteur)"}, {"geweldige", "great, extraordinary (geweldig)"} },
},

[1137] = { en = "News for Fizzle", tier = 3,
  t = "Nieuws voor Fizzle",
  d = "Indurium is ongelooflijk goed bestand tegen hitte! Ik weet zeker dat het geschikt is voor de zuigers van Fizzle. Maar hij heeft echt indurium-erts nodig, niet alleen de schilfers.$B$BHet erts moet diep in Uldaman worden gedolven, aan de noordgrens van de Badlands. Dat is de echte bron van indurium.$B$BDoe Fizzle Brassbolts de groeten van mij en vertel hem wat ik jou heb verteld.$B$BGoede reis, $N. Het zou me niet verbazen als we elkaar weer zien. Zodra Fizzle van indurium hoort, stuurt hij je waarschijnlijk naar Uldaman om het te halen!",
  o = "Spreek met Fizzle Brassbolts op de Shimmering Flats.",
  c = "$N, je bent terug! Heb je Martek gevonden? Heb je met hem gesproken? Wat zei hij? Kan hij helpen??$b$bVertel, vertel, vertel!!",
  g = { {"ongelooflijk", "incredibly"}, {"bestand tegen", "resistant to"}, {"hitte", "heat"}, {"geschikt", "suitable"}, {"zuigers", "pistons (zuiger)"}, {"erts", "ore"}, {"schilfers", "flakes (schilfer)"}, {"gedolven", "mined (delven)"}, {"noordgrens", "northern border"}, {"bron", "source"}, {"verbazen", "to surprise"}, {"Zodra", "as soon as"} },
},

[1108] = { en = "Indurium", tier = 3,
  t = "Indurium",
  d = "Ik ben hier niet alleen om bij mensen weg te blijven. Er is heel veel metaal in de Badlands, $N, als je het lef hebt om het te halen.$B$BHet metaal heet indurium. En toevallig zou het volgens de geruchten goed bestand zijn tegen hitte en belasting. Het zou kunnen werken voor de auto van Fizzle.$B$BMaar laten we het zeker weten. Breng me monsters van indurium, dan test ik de eigenschappen.$B$BEcht indurium-erts ligt diep in Uldaman, maar de Stonevault troggs in de Badlands hebben soms schilfers ervan bij zich. Breng me die schilfers.",
  o = "Breng 10 Indurium Flakes naar Martek the Exiled in de Badlands.",
  p = "Heb je indurium-schilfers gevonden, $N? Mijn smidse is opgewarmd en klaar om ze te testen.",
  c = "Ah ja, deze zijn prima. Laten we ze nu wat verhitten en kijken hoe ze het doen...",
  g = { {"weg te blijven", "to stay away (wegblijven)"}, {"lef", "guts, nerve"}, {"toevallig", "as luck would have it"}, {"volgens de geruchten", "it is rumored"}, {"bestand", "resistant"}, {"belasting", "stress, load"}, {"monsters", "samples (monster)"}, {"eigenschappen", "properties (eigenschap)"}, {"schilfers", "flakes (schilfer)"}, {"smidse", "forge"}, {"opgewarmd", "heated up (opwarmen)"}, {"verhitten", "to heat"} },
},

[1187] = { en = "Razzeric's Tweaking", tier = 3,
  t = "De aanpassingen van Razzeric",
  d = "Pozzik is een geweldige monteur, dat weet ik. Maar hij durft niet gewoon flink wat vuurkracht toe te voegen en zich vast te houden tijdens de rit. Ik wel.$b$bAls Pozzik klaar is met een racewagen, neem ik even de tijd om mijn eigen aanpassingen te doen. Je weet wel: de besturing losser maken, delen van het frame weghalen en er meer vermogen in stoppen!$b$bIk had een seaforium-booster besteld bij Shreev in de Gizmorium in Gadgetzan. Maar blijkbaar is de zeppelin waarmee hij werd verstuurd neergestort in Dustwallow Marsh! Ik moet hem hebben, $n!",
  o = "Haal de Seaforium Booster op voor Razzeric op de Shimmering Flats.",
  p = "Hoe kan ik me nou op de baan laten zien zonder een extra duwtje om op gang te komen? Het is een schande, zeg ik je.",
  c = "Moet je dit pareltje eens zien! Vijftien pond pure seaforiumkracht! Zodra ik dit aan de zijkant van mijn racewagen heb vastgemaakt, ga ik zo snel over de baan dat ik de gnomen twee keer versla!",
  g = { {"durft", "dares (durven)"}, {"vuurkracht", "firepower"}, {"rit", "ride"}, {"besturing", "controls, steering"}, {"losser", "looser (los)"}, {"weghalen", "to remove"}, {"vermogen", "power"}, {"besteld", "ordered (bestellen)"}, {"blijkbaar", "apparently"}, {"neergestort", "crashed (neerstorten)"}, {"duwtje", "little push, kick"}, {"op gang te komen", "to get going (op gang komen)"}, {"schande", "disgrace, travesty"}, {"pareltje", "little gem, beauty"}, {"vastgemaakt", "strapped on, fastened (vastmaken)"}, {"versla", "beat (verslaan)"} },
},

[1188] = { en = "Safety First", tier = 3,
  t = "Veiligheid voor alles",
  d = "Maar wacht, wat is dit? Shreev heeft de beveiliging aan laten staan. Dat beperkt hoeveel kracht ik op elk moment uit de booster kan halen. Ik had hem gezegd dat ik die uit wilde hebben! Dit is niet goed.$b$bJe moet dit naar de Gadgetzan Gizmorium in de Tanaris Desert brengen en Shreev dit laten weghalen.",
  o = "Breng de Seaforium Booster naar Shreev in Gadgetzan.",
  p = "Zoals je vast weet, kan de Gizmorium je helpen met alles wat je nodig hebt om te knutselen! Wat kan ik voor je doen?",
  c = "Alleen Razzeric kan hiernaar kijken en zeggen dat ik er op de een of andere manier een veiligheidsslot op heb gezet. Deze booster bestaat bijna helemaal uit seaforium-explosieven. Ik had hem al aangepast, zodat er meer van de lading vrijkomt bij gebruik. Maar Razzeric is pas tevreden als alles op elf staat!",
  g = { {"beveiliging", "safety (catch)"}, {"beperkt", "limits (beperken)"}, {"weghalen", "to remove"}, {"knutselen", "to tinker"}, {"veiligheidsslot", "safety lock"}, {"bestaat ... uit", "consists of (bestaan uit)"}, {"explosieven", "explosives"}, {"aangepast", "modified (aanpassen)"}, {"lading", "payload, charge"}, {"vrijkomt", "is released (vrijkomen)"}, {"tevreden", "content, satisfied"}, {"als alles op elf staat", "unless it goes to eleven (turned up past the maximum)"} },
},

[1189] = { en = "Safety First", tier = 3,
  t = "Veiligheid voor alles",
  d = "Zo, ik heb gedaan wat Razzeric wilde. Zeg hem maar dat hij voorzichtig moet zijn als hij dit laat afgaan. Als hij ook maar de kleinste fout maakt, gaat hij niet vooruit. Dan is hij alleen nog een verbrande plek op de baan.$b$bDat zou ook zonde zijn. Wie weet of onze negentiende coureur iets zou kunnen?",
  o = "Breng de Modified Seaforium Booster terug naar Razzeric op de Shimmering Flats.",
  p = "Kun je geloven dat Pozzik een emmer zand op de racewagen heeft gezet? Hoe moet ik mijn topsnelheid halen met een emmer zand onder mijn stoel?",
  c = "Zo mag ik het horen! Ik wou dat ik de blik in de ogen van de gnomen kon zien als ik dit schatje laat afgaan.$b$bJammer dat ik het te druk heb met het vestigen van een nieuw baanrecord!",
  g = { {"voorzichtig", "careful"}, {"laat afgaan", "sets off (laten afgaan)"}, {"ook maar de kleinste", "even the slightest"}, {"verbrande", "burnt (verbrand)"}, {"zonde", "a shame"}, {"negentiende", "nineteenth"}, {"coureur", "racing driver"}, {"emmer", "bucket"}, {"topsnelheid", "maximum speed"}, {"Zo mag ik het horen", "now that's more like it"}, {"schatje", "baby, sweetheart"}, {"vestigen", "to set (a record)"} },
},

[1190] = { en = "Keeping Pace", tier = 3,
  t = "Bijblijven",
  d = "De gebroeders Brassbolts hebben een nieuw bouwmateriaal ontdekt. Dat is de enige verklaring die klopt. Hun wagens rijden sneller dan vroeger. Maar hun ontwerpen, en alle andere gegevens die we bij hun ritten hebben verzameld, zijn precies hetzelfde.$b$bWat we wel weten: Rizzle Brassbolts is bijna voortdurend bezig met de plannen voor deze nieuwe ontdekking.$b$bZamek kan voor afleiding zorgen, zodat jij die plannen van hen kunt stelen.",
  o = "Laat Zamek voor afleiding zorgen en steel dan de plannen van Rizzle voor Pozzik op de Shimmering Flats.",
  c = "Een rol met aantekeningen en ontwerpen, haastig en slordig geschreven, over het verfijnen van een of andere grondstof.",
  g = { {"Bijblijven", "keeping pace"}, {"gebroeders", "brothers"}, {"bouwmateriaal", "building material"}, {"verklaring", "explanation"}, {"gegevens", "data"}, {"verzameld", "gathered (verzamelen)"}, {"voortdurend", "constantly"}, {"ontdekking", "discovery"}, {"afleiding", "diversion, distraction"}, {"rol", "scroll"}, {"haastig", "hasty"}, {"slordig", "messy, sloppy"}, {"verfijnen", "refining"}, {"grondstof", "raw material"} },
},

