[1194] = { en = "Rizzle's Schematics", tier = 3,
  t = "De schema's van Rizzle",
  d = "De schema's van Rizzle beschrijven hoe indurium-erts wordt verfijnd. Uit zijn gekrabbel blijkt dat het indurium-erts uit Uldaman in de Badlands komt, een opgraving van de dwergen.$b$bVeel van de andere aantekeningen gaan over hoe goed het tegen hitte bestand is.$b$bOp de plannen ligt, als presse-papier, een brok van wat onbewerkt indurium-erts lijkt te zijn.",
  o = "Breng de Sample of Indurium Ore naar Pozzik op de Shimmering Flats.",
  c = "Indurium? Interessant... Als het zo goed tegen hitte kan als jij zegt, dan verklaart dat waarom de gnomen de laatste tijd zoveel beter presteren.$B$BDit monster dat je me hebt gebracht is ook van onschatbare waarde. Ik kan er wat tests mee doen, maar ik heb er meer van nodig voordat we er echt iets aan hebben.",
